import sys

def main():
    n = int(sys.stdin.readline().strip())
    if n <= 0:
        return

    lines = []
    for i in range(n):
        start_idx = ord('A') + i
        line = ''.join(chr(start_idx + j) for j in range(n - i))
        if i > 0:
            line = ' ' + line
        lines.append(line)

    # Print first half (upper part)
    for line in lines:
        print(line + ' ')

    # Print second half (lower part, excluding the last line)
    for line in reversed(lines[:-1]):
        print(line + ' ')

if __name__ == "__main__":
    main()
